/* @autogenerated */
import { Injector, runInInjectionContext } from '@angular/core';
import { toObservable } from '@angular/core/rxjs-interop';
import { Params } from '@angular/router';
import { Subscription } from 'rxjs';
import {
  LocalRouteStateBind,
  LocalRouteStateService,
} from 'app/shared/interaction/local-route-state/local-route-state.service';
import type { ItemMapper } from './action-container.component';

export type RunAction = (action?: string, items?: any[]) => void;

/**
 * Refleja la acción activa de un contenedor en la URL (`?<name>=<action>[:<key>]`)
 * y la reactiva al navegar, cargando el elemento con el `ItemMapper`.
 */
export class ActionRouteSync {
  private bind?: LocalRouteStateBind;
  private watchSubscription?: Subscription;
  private loadSubscription?: Subscription;

  constructor(
    private readonly localRouter: LocalRouteStateService,
    private readonly injector: Injector,
  ) {}

  get bound(): boolean {
    return !!this.bind;
  }

  connect(name: string, mapper: ItemMapper<any>, run: RunAction): void {
    this.bind = this.localRouter.bind([name]);
    this.watchSubscription?.unsubscribe();
    this.watchSubscription = this.bind.watch().subscribe((values: Params) => {
      this.loadSubscription?.unsubscribe();
      const value: string | undefined = values[name];
      if (!value) {
        run();
        return;
      }
      const [action, ...rest] = value.split(':');
      const key = rest.join(':');
      if (!key) {
        run(action);
        return;
      }
      setTimeout(() => {
        const loader = mapper.load(key);
        runInInjectionContext(this.injector, () => {
          this.loadSubscription = toObservable(loader).subscribe((item) => {
            if (item) {
              run(action, [item]);
            }
          });
        });
      });
    });
  }

  go(name: string, value?: string): void {
    this.bind?.go(value ? { [name]: value } : {});
  }

  disconnect(): void {
    this.watchSubscription?.unsubscribe();
    this.loadSubscription?.unsubscribe();
  }
}
